"""Semantic version ordering."""


def _pre_key(pre):
    # Semver: numeric identifiers compare numerically and sort before
    # alphanumeric ones; a shorter identifier list sorts first when equal.
    parts = []
    for ident in pre.split("."):
        if ident.isdigit():
            parts.append((0, int(ident), ""))
        else:
            parts.append((1, 0, ident))
    return tuple(parts)


def key(version):
    """Sort key: a pre-release (1.0.0-alpha) sorts before its release (1.0.0)."""
    core, _, pre = version.partition("-")
    nums = tuple(int(x) for x in core.split("."))
    if pre:
        # flag 0: pre-release, ordered by its identifiers
        return (nums, 0, _pre_key(pre))
    # flag 1: a release sorts after every pre-release of the same core
    return (nums, 1, ())
EOF
